      --text-primary: oklch(21% 0.015 240);
      --text-secondary: oklch(43% 0.02 235);
      --text-link: oklch(50% 0.02 235);
      --brand: oklch(38% 0.08 220);
      --brand-soft: oklch(70% 0.04 220);
      --border: oklch(85% 0.01 235);
      --focus: oklch(55% 0.12 230);
      --shadow: 0 14px 40px oklch(20% 0.01 240 / 0.08);

      --radius-sm: 10px;
      --radius-md: 14px;
      --radius-lg: 18px;

      --space-1: clamp(0.5rem, 0.45rem + 0.2vw, 0.65rem);
      --space-2: clamp(0.75rem, 0.7rem + 0.3vw, 1rem);
      --space-3: clamp(1rem, 0.9rem + 0.5vw, 1.3rem);
      --space-4: clamp(1.4rem, 1.2rem + 0.8vw, 2rem);
      --space-5: clamp(1.8rem, 1.5rem + 1vw, 2.8rem);
      --space-6: clamp(2.4rem, 2rem + 1.6vw, 4rem);

      --container: min(92vw, 44rem);
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "DM Sans", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.45;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
      display: grid;
      place-items: center;
      padding: var(--space-5) var(--space-3) calc(var(--space-5) + 84px);
    }

    .page-shell {
      width: var(--container);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: clamp(1.5rem, 1.2rem + 1.2vw, 2.6rem);
      box-shadow: var(--shadow);
      text-align: center;
    }

    .logo {
      margin: 0 auto var(--space-5);
      width: fit-content;
      display: inline-flex;
      align-items: center;
      gap: 0.65rem;
      text-decoration: none;
      color: var(--brand);
      font-weight: 700;
      letter-spacing: 0.01em;
      font-size: clamp(1.06rem, 1rem + 0.35vw, 1.25rem);
    }

    .logo-mark {
      width: 1.9rem;
      height: 1.9rem;
      border-radius: 50%;
      background: linear-gradient(150deg, oklch(45% 0.12 220), oklch(68% 0.08 205));
      position: relative;
      box-shadow: 0 4px 12px oklch(35% 0.1 220 / 0.2);
    }

    .logo-mark::before {
      content: "";
      position: absolute;
      inset: 26% 29%;
      border-radius: 999px;
      border: 2px solid oklch(99% 0 0 / 0.92);
    }

    h1 {
      margin: 0;
      font-size: clamp(1.35rem, 1.15rem + 1vw, 2.05rem);
      font-weight: 650;
      letter-spacing: -0.01em;
    }

    .lead {
      margin: var(--space-2) auto var(--space-4);
      max-width: 38ch;
      color: var(--text-secondary);
      font-size: clamp(0.98rem, 0.92rem + 0.2vw, 1.05rem);
    }

    .search-wrap {
      margin: 0 auto var(--space-4);
      width: min(100%, 34rem);
    }

    .search-form {
      position: relative;
    }

    .search-input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: var(--surface);
      color: var(--text-primary);
      font: inherit;
      font-size: 1rem;
      padding: 0.95rem 3.15rem 0.95rem 1rem;
      transition: border-color 140ms ease, box-shadow 140ms ease;
    }

    .search-input::placeholder {
      color: oklch(58% 0.012 235);
    }

    .search-input:focus-visible,
    .search-button:focus-visible,
    .text-link:focus-visible,
    .cookie-button:focus-visible,
    .modal-close:focus-visible,
    .modal-action:focus-visible,
    .modal-link:focus-visible {
      outline: 2px solid var(--focus);
      outline-offset: 2px;
    }

    .search-input:focus {
      border-color: var(--brand-soft);
      box-shadow: 0 0 0 4px oklch(82% 0.04 220 / 0.35);
    }

    .search-button {
      position: absolute;
      top: 50%;
      right: 0.5rem;
      transform: translateY(-50%);
      border: 0;
      background: var(--surface-muted);
      color: var(--brand);
      width: 2.2rem;
      height: 2.2rem;
      border-radius: 0.65rem;
      cursor: pointer;
      display: grid;
      place-items: center;
    }

    .search-button:hover {
      background: oklch(92% 0.02 220);
    }

    .error-code {
      margin: 0 auto var(--space-4);
      width: min(100%, 34rem);
      border-radius: var(--radius-sm);
      background: var(--surface-muted);
      color: oklch(54% 0.01 240);
      font-weight: 600;
      font-size: 0.93rem;
      padding: 0.8rem 1rem;
      letter-spacing: 0.015em;
      text-transform: uppercase;
      border: 1px solid var(--border);
    }

    .error-anchor {
      margin: 0 0 var(--space-4);
      font-weight: 700;
      line-height: 1;
      font-size: clamp(3.1rem, 2.2rem + 4vw, 6rem);
      color: oklch(83% 0.012 235);
      letter-spacing: 0.05em;
      user-select: none;
    }

    .divider {
      border: none;
      border-top: 1px solid var(--border);
      margin: 0 0 var(--space-4);
    }

    h2 {
      margin: 0 0 var(--space-2);
      font-size: 1.03rem;
      font-weight: 600;
      color: var(--text-primary);
    }

    .link-row {
      display: flex;
      flex-direction: column;
      gap: 0.55rem;
      align-items: center;
    }

    .text-link {
      color: var(--text-link);
      text-decoration-thickness: 0.08em;
      text-underline-offset: 0.14em;
      transition: color 130ms ease;
      font-size: 0.98rem;
    }

    .text-link:hover { color: var(--brand); }

    .cookie-banner {
      position: fixed;
      left: 50%;
      bottom: 0.85rem;
      transform: translateX(-50%);
      width: min(96vw, 68rem);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow);
      padding: 0.8rem 0.95rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.9rem;
      z-index: 30;
    }

    .cookie-copy {
      margin: 0;
      font-size: 0.86rem;
      color: var(--text-secondary);
    }

    .cookie-copy a,
    .modal-link {
      color: var(--brand);
    }

    .cookie-button,
    .modal-action,
    .modal-close {
      border: 1px solid var(--border);
      background: var(--surface-muted);
      color: var(--text-primary);
      border-radius: 0.62rem;
      font: inherit;
      font-size: 0.86rem;
      font-weight: 600;
      padding: 0.54rem 0.85rem;
      cursor: pointer;
      white-space: nowrap;
    }

    .cookie-button:hover,
    .modal-action:hover,
    .modal-close:hover {
      background: oklch(93% 0.01 235);
    }

    .cookie-banner[hidden],
    .cookie-modal[hidden] {
      display: none;
    }

    .cookie-modal {
      position: fixed;
      inset: 0;
      background: oklch(16% 0.01 250 / 0.44);
      z-index: 40;
      display: grid;
      place-items: center;
      padding: var(--space-3);
    }

    .modal-panel {
      width: min(92vw, 34rem);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: var(--space-4);
      box-shadow: var(--shadow);
    }

    .modal-title {
      margin: 0 0 0.45rem;
      font-size: 1.1rem;
    }

    .modal-text {
      margin: 0 0 var(--space-3);
      font-size: 0.92rem;
      color: var(--text-secondary);
    }

    .pref-list {
      display: grid;
      gap: 0.62rem;
      margin: 0 0 var(--space-3);
      padding: 0;
      list-style: none;
    }

    .pref-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      border: 1px solid var(--border);
      border-radius: 0.65rem;
      padding: 0.55rem 0.65rem;
      font-size: 0.9rem;
      color: var(--text-primary);
      background: var(--surface-muted);
    }

    .pref-item input[type="checkbox"] {
      width: 1rem;
      height: 1rem;
      accent-color: oklch(50% 0.1 225);
    }

    .modal-actions {
      display: flex;
      gap: 0.6rem;
      justify-content: flex-end;
      flex-wrap: wrap;
    }

    .modal-action.primary {
      background: var(--brand);
      border-color: var(--brand);
      color: oklch(99% 0 0);
    }

    .modal-action.primary:hover {
      background: oklch(34% 0.08 220);
    }

    @media (max-width: 42rem) {
      .cookie-banner {
        align-items: stretch;
        flex-direction: column;
      }

      .cookie-button {
        align-self: flex-end;
      }

      .page-shell {
        padding: 1.25rem;
      }
    }
  </style>
</head>
<body>
  <main class="page-shell" aria-labelledby="error-title">
    <a class="logo" href="./" aria-label="IdeaForum home">
      <span class="logo-mark" aria-hidden="true"></span>
      <span>IdeaForum</span>
    </a>

    <h1 id="error-title">Sorry, we can&#39;t find that.</h1>
    <p class="lead">Perhaps we can help you find the content you&#39;re looking for:</p>

    <section class="search-wrap" aria-label="Search IdeaForum">
      <form class="search-form" id="searchForm" action="./search.html" method="get">
        <label for="siteSearch" class="sr-only" style="position:absolute;left:-9999px">Search IdeaForum</label>
        <input
          id="siteSearch"
          class="search-input"
          name="q"
          type="search"
          placeholder="Search IdeaForum..."
          autocomplete="off"
          required
        />
        <button class="search-button" type="submit" aria-label="Search">
          <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="11" cy="11" r="7"></circle>
            <line x1="20" y1="20" x2="16.65" y2="16.65"></line>
          </svg>
        </button>
      </form>
    </section>

    <div class="error-code">HTTP Error 404</div>
    <div class="error-anchor" aria-hidden="true">404</div>

    <hr class="divider" />

    <section aria-label="Next steps">
      <h2>What&#39;s next?</h2>
      <div class="link-row">
        <a class="text-link" href="./">Go to the homepage</a>
        <a class="text-link" href="./help-desk.html">Visit our Help Desk</a>
      </div>
    </section>
  </main>

  <aside class="cookie-banner" id="cookieBanner" role="region" aria-label="Cookie consent banner">
    <p class="cookie-copy">
      This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link:
      <a href="./privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
    </p>
    <button class="cookie-button" id="managePreferences" type="button">Manage Preferences</button>
  </aside>

  <div class="cookie-modal" id="cookieModal" hidden>
    <div class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="cookieModalTitle">
      <h3 class="modal-title" id="cookieModalTitle">Cookie Preferences</h3>
      <p class="modal-text">
        Choose which optional cookies IdeaForum may use. Essential cookies remain active to keep the site functional.
        Review details in our <a class="modal-link" href="./privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>.
      </p>

      <ul class="pref-list">
        <li class="pref-item"><span>Essential Cookies</span><input type="checkbox" checked disabled aria-label="Essential Cookies always enabled" /></li>
        <li class="pref-item"><label for="analyticsOpt">Analytics Cookies</label><input id="analyticsOpt" type="checkbox" checked /></li>
        <li class="pref-item"><label for="personalizationOpt">Personalization Cookies</label><input id="personalizationOpt" type="checkbox" /></li>
        <li class="pref-item"><label for="advertisingOpt">Targeted Advertising Cookies</label><input id="advertisingOpt" type="checkbox" /></li>
      </ul>

      <div class="modal-actions">
        <button class="modal-close" id="closeModal" type="button">Cancel</button>
        <button class="modal-action" id="savePrefs" type="button">Save Preferences</button>
        <button class="modal-action primary" id="acceptAll" type="button">Accept All</button>
      </div>
    </div>
  </div>

  <script>
    (function () {
      const form = document.getElementById('searchForm');
      const input = document.getElementById('siteSearch');
      const banner = document.getElementById('cookieBanner');
      const modal = document.getElementById('cookieModal');
      const openBtn = document.getElementById('managePreferences');
      const closeBtn = document.getElementById('closeModal');
      const saveBtn = document.getElementById('savePrefs');
      const acceptAllBtn = document.getElementById('acceptAll');

      const PREFS_KEY = 'ideaforum-cookie-prefs-v1';

      function hideBanner() {
        banner.hidden = true;
      }

      function showBannerIfNeeded() {
        if (!localStorage.getItem(PREFS_KEY)) {
          banner.hidden = false;
        } else {
          hideBanner();
        }
      }

      function collectPreferences(forceAll) {
        return {
          essential: true,
          analytics: forceAll ? true : document.getElementById('analyticsOpt').checked,
          personalization: forceAll ? true : document.getElementById('personalizationOpt').checked,
          advertising: forceAll ? true : document.getElementById('advertisingOpt').checked,
          updatedAt: new Date().toISOString()
        };
      }

      function persistPreferences(forceAll) {
        localStorage.setItem(PREFS_KEY, JSON.stringify(collectPreferences(forceAll)));
        modal.hidden = true;
        hideBanner();
      }

      function openModal() {
        modal.hidden = false;
        closeBtn.focus();
      }

      function closeModal() {
        modal.hidden = true;
      }

      form.addEventListener('submit', function (event) {
        event.preventDefault();
        const query = input.value.trim();
        if (!query) return;
        const target = new URL('./search.html', window.location.href);
        target.searchParams.set('q', query);
        window.location.href = target.toString();
      });

      openBtn.addEventListener('click', openModal);
      closeBtn.addEventListener('click', closeModal);
      saveBtn.addEventListener('click', function () { persistPreferences(false); });
      acceptAllBtn.addEventListener('click', function () { persistPreferences(true); });

      modal.addEventListener('click', function (event) {
        if (event.target === modal) closeModal();
      });

      document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape' && !modal.hidden) closeModal();
      });

      showBannerIfNeeded();
    })();
  </script>
</body>
</html>
