      background: oklch(93% 0.01 235);
    }

    .cookie-banner[hidden],
    .cookie-modal[hidden] {
      display: none;
    }

    .cookie-modal {
      position: fixed;
      inset: 0;
      background: oklch(16% 0.01 250 / 0.44);
      z-index: 40;
      display: grid;
      place-items: center;
      padding: var(--space-3);
    }

    .modal-panel {
      width: min(92vw, 34rem);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: var(--space-4);
      box-shadow: var(--shadow);
    }

    .modal-title {
      margin: 0 0 0.45rem;
      font-size: 1.1rem;
    }

    .modal-text {
      margin: 0 0 var(--space-3);
      font-size: 0.92rem;
      color: var(--text-secondary);
    }

    .pref-list {
      display: grid;
      gap: 0.62rem;
      margin: 0 0 var(--space-3);
      padding: 0;
      list-style: none;
    }

    .pref-item {
      display: flex;
      align-items: center;
      justify-content: space-between;
      border: 1px solid var(--border);
      border-radius: 0.65rem;
      padding: 0.55rem 0.65rem;
      font-size: 0.9rem;
      color: var(--text-primary);
      background: var(--surface-muted);
    }

    .pref-item input[type="checkbox"] {
      width: 1rem;
      height: 1rem;
      accent-color: oklch(50% 0.1 225);
    }

    .modal-actions {
      display: flex;
      gap: 0.6rem;
      justify-content: flex-end;
      flex-wrap: wrap;
    }

    .modal-action.primary {
      background: var(--brand);
      border-color: var(--brand);
      color: oklch(99% 0 0);
    }

    .modal-action.primary:hover {
      background: oklch(34% 0.08 220);
    }

    @media (max-width: 42rem) {
      .cookie-banner {
        align-items: stretch;
        flex-direction: column;
      }

      .cookie-button {
        align-self: flex-end;
      }

      .page-shell {
        padding: 1.25rem;
      }
    }
  </style>
</head>
<body>
  <main class="page-shell" aria-labelledby="error-title">
    <a class="logo" href="./" aria-label="IdeaForum home">
      <span class="logo-mark" aria-hidden="true"></span>
      <span>IdeaForum</span>
    </a>

    <h1 id="error-title">Sorry, we can&#39;t find that.</h1>
    <p class="lead">Perhaps we can help you find the content you&#39;re looking for:</p>

    <section class="search-wrap" aria-label="Search IdeaForum">
      <form class="search-form" id="searchForm" action="./search.html" method="get">
        <label for="siteSearch" class="sr-only" style="position:absolute;left:-9999px">Search IdeaForum</label>
        <input
          id="siteSearch"
          class="search-input"
          name="q"
          type="search"
          placeholder="Search IdeaForum..."
          autocomplete="off"
          required
        />
        <button class="search-button" type="submit" aria-label="Search">
          <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="11" cy="11" r="7"></circle>
            <line x1="20" y1="20" x2="16.65" y2="16.65"></line>
          </svg>
        </button>
      </form>
    </section>

    <div class="error-code">HTTP Error 404</div>
    <div class="error-anchor" aria-hidden="true">404</div>

    <hr class="divider" />

    <section aria-label="Next steps">
      <h2>What&#39;s next?</h2>
      <div class="link-row">
        <a class="text-link" href="./">Go to the homepage</a>
        <a class="text-link" href="./help-desk.html">Visit our Help Desk</a>
      </div>
    </section>
  </main>

  <aside class="cookie-banner" id="cookieBanner" role="region" aria-label="Cookie consent banner">
    <p class="cookie-copy">
      This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link:
      <a href="./privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
    </p>
    <button class="cookie-button" id="managePreferences" type="button">Manage Preferences</button>
  </aside>

  <div class="cookie-modal" id="cookieModal" hidden>
    <div class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="cookieModalTitle">
      <h3 class="modal-title" id="cookieModalTitle">Cookie Preferences</h3>
      <p class="modal-text">
        Choose which optional cookies IdeaForum may use. Essential cookies remain active to keep the site functional.
        Review details in our <a class="modal-link" href="./privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>.
      </p>

      <ul class="pref-list">
        <li class="pref-item"><span>Essential Cookies</span><input type="checkbox" checked disabled aria-label="Essential Cookies always enabled" /></li>
        <li class="pref-item"><label for="analyticsOpt">Analytics Cookies</label><input id="analyticsOpt" type="checkbox" checked /></li>
        <li class="pref-item"><label for="personalizationOpt">Personalization Cookies</label><input id="personalizationOpt" type="checkbox" /></li>
        <li class="pref-item"><label for="advertisingOpt">Targeted Advertising Cookies</label><input id="advertisingOpt" type="checkbox" /></li>
      </ul>

      <div class="modal-actions">
        <button class="modal-close" id="closeModal" type="button">Cancel</button>
        <button class="modal-action" id="savePrefs" type="button">Save Preferences</button>
        <button class="modal-action primary" id="acceptAll" type="button">Accept All</button>
      </div>
    </div>
  </div>

  <script>
    (function () {
      const form = document.getElementById('searchForm');
      const input = document.getElementById('siteSearch');
      const banner = document.getElementById('cookieBanner');
      const modal = document.getElementById('cookieModal');
      const openBtn = document.getElementById('managePreferences');
      const closeBtn = document.getElementById('closeModal');
      const saveBtn = document.getElementById('savePrefs');
      const acceptAllBtn = document.getElementById('acceptAll');

      const PREFS_KEY = 'ideaforum-cookie-prefs-v1';

      function hideBanner() {
        banner.hidden = true;
      }

      function showBannerIfNeeded() {
        if (!localStorage.getItem(PREFS_KEY)) {
          banner.hidden = false;
        } else {
          hideBanner();
        }
      }

      function collectPreferences(forceAll) {
        return {
          essential: true,
          analytics: forceAll ? true : document.getElementById('analyticsOpt').checked,
          personalization: forceAll ? true : document.getElementById('personalizationOpt').checked,
          advertising: forceAll ? true : document.getElementById('advertisingOpt').checked,
          updatedAt: new Date().toISOString()
        };
      }

      function persistPreferences(forceAll) {
        localStorage.setItem(PREFS_KEY, JSON.stringify(collectPreferences(forceAll)));
        modal.hidden = true;
        hideBanner();
      }

      function openModal() {
        modal.hidden = false;
        closeBtn.focus();
      }

      function closeModal() {
        modal.hidden = true;
      }

      form.addEventListener('submit', function (event) {
        event.preventDefault();
        const query = input.value.trim();
        if (!query) return;
        const target = new URL('./search.html', window.location.href);
        target.searchParams.set('q', query);
        window.location.href = target.toString();
      });

      openBtn.addEventListener('click', openModal);
      closeBtn.addEventListener('click', closeModal);
      saveBtn.addEventListener('click', function () { persistPreferences(false); });
      acceptAllBtn.addEventListener('click', function () { persistPreferences(true); });

      modal.addEventListener('click', function (event) {
        if (event.target === modal) closeModal();
      });

      document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape' && !modal.hidden) closeModal();
      });

      showBannerIfNeeded();
    })();
  </script>
</body>
</html>
